            rootId = $RootId
            timestamp = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
            payload = $Payload
        }
        Write-McpYamlObject -Path $path -Document $record
        return $path
    } catch {
        return ''
    }
}

