    $resolved = (Resolve-Path -LiteralPath $path).ProviderPath
    $item = Get-Item -LiteralPath $resolved
    return [ordered]@{
        markerFilePath = $resolved
        markerLastWriteUtc = $item.LastWriteTimeUtc.ToString('O')
