+# SPDX-License-Identifier: Apache-2.0
+#Requires -Version 7.0
+<#
+.SYNOPSIS
+Persists, verifies, completes, or redacts only this reviewer turn and its receipts.
+.PARAMETER Stage
+Protect redacts receipt secrets. Persist records both full receipts and verifies
+readback. Complete closes the already verified reviewer turn and verifies again.
+#>
+[CmdletBinding(SupportsShouldProcess)]
+param([Parameter(Mandatory)][ValidateSet('Protect','Persist','Complete')][string]$Stage)
+$ErrorActionPreference='Stop'
+Import-Module powershell-yaml
+$receiptRoot=Join-Path (Get-Location).Path 'docs/receipts/hv'
+$mdPath=Join-Path $receiptRoot 'hostile-validator-plan-readiness-merged-r4-20261012T034439Z.md'
+$jsonPath=Join-Path $receiptRoot 'hostile-validator-plan-readiness-merged-r4-20261012T034439Z.json'
+$proofPath=Join-Path $receiptRoot '20261012T034439Z-persistence-proof.json'
+$wrapper='/home/sharpninja/.codex/plugins/cache/mcpserver-codex-plugin/mcpserver/1.119.0/Invoke-CodexMcpPlugin.ps1'
+$reviewSession='Codex-20261012T034800Z-hv-plan-readiness-r4'
+$reviewRequest='req-20261012T034439Z-hv-merged-r4'
+
+function Invoke-ReviewerMethod {
+    <# .SYNOPSIS Sends an authorized reviewer operation through the installed wrapper. #>
+    [CmdletBinding()]
+    param([Parameter(Mandatory)][string]$Method,[Parameter(Mandatory)][hashtable]$Parameters)
+    $raw=& $wrapper -Command Invoke -Method $Method -ParamsObject $Parameters -WorkspacePath $env:MCP_WORKSPACE_PATH -CacheRoot $env:MCP_CACHE_DIR_OVERRIDE | Out-String
+    $result=ConvertFrom-Yaml -Yaml $raw
+    if($result.type -ne 'result'){throw ('Reviewer method failed: '+$Method+' '+$raw)}
+    if($Method -like 'workflow.sessionlog.*' -and $result.payload.result.persisted -ne $true){throw ('Reviewer persistence not confirmed: '+$Method+' '+$raw)}
+    return $result.payload.result
+}
+
+function Get-ReviewerReceiptProof {
+    <# .SYNOPSIS Reads this exact reviewer turn and compares both stored receipts. #>
+    [CmdletBinding()]
+    param()
+    # The installed client exposes its scalar QueryAsync overload through the REPL.
+    $q=Invoke-ReviewerMethod -Method 'client.SessionLog.QueryAsync' -Parameters @{agent='Codex';text='20261012T034439Z';limit=5;offset=0}
+    $s=@($q.items | Where-Object sessionId -eq $reviewSession)
+    if($s.Count -ne 1){throw 'Expected exactly one reviewer session in readback.'}
+    $turn=@($s[0].turns | Where-Object requestId -eq $reviewRequest)
+    if($turn.Count -ne 1){throw 'Expected exactly one reviewer turn in readback.'}
+    $md=[IO.File]::ReadAllText($mdPath)
+    $js=[IO.File]::ReadAllText($jsonPath)
+    $parts=@($turn[0].processingDialog | Where-Object { $_.content.StartsWith('R4 JSON RECEIPT PART ') })
+    $rejoined=[string]::Concat([string[]]@($parts | ForEach-Object { $_.content.Substring($_.content.IndexOf("`n")+1) }))
+    $mdEqual=[string]::Equals($md,[string]$turn[0].response,[StringComparison]::Ordinal)
+    $jsonEqual=[string]::Equals($js,$rejoined,[StringComparison]::Ordinal)
+    if(-not $mdEqual -or -not $jsonEqual){throw "Reviewer readback differs: markdown=$mdEqual json=$jsonEqual parts=$($parts.Count)"}
+    return [ordered]@{
+        TimestampUtc=[DateTime]::UtcNow.ToString('o'); Agent='Codex'; SessionId=$reviewSession; RequestId=$reviewRequest
+        Status=$turn[0].status; MarkdownEqual=$mdEqual; JsonEqual=$jsonEqual; JsonDialogParts=$parts.Count
+        MarkdownSha256=(Get-FileHash -LiteralPath $mdPath -Algorithm SHA256).Hash
+        JsonSha256=(Get-FileHash -LiteralPath $jsonPath -Algorithm SHA256).Hash
+        MarkdownCharacters=$md.Length; JsonCharacters=$js.Length
+        ReadbackMethod='client.SessionLog.QueryAsync via installed Codex wrapper; exact session/request selected from returned items'
+    }
+}
+
+if($Stage -eq 'Protect'){
+    $secrets=@()
+    foreach($markerPath in @('/home/sharpninja/github/McpServer/AGENTS-README-FIRST.yaml','AGENTS-README-FIRST.yaml')){
+        $m=ConvertFrom-Yaml -Yaml (Get-Content -LiteralPath $markerPath -Raw)
+        $secrets+= $m.apiKey
+        $secrets+= $m.api_key
+    }
+    $secrets=@($secrets | Where-Object { $_ -and $_.Length -ge 20 } | Sort-Object -Unique)
+    $files=@(Get-ChildItem -LiteralPath $receiptRoot -File | Where-Object { $_.Name -like '*20261012T034439Z*' -and $_.Extension -in @('.md','.json','.jsonl','.ps1') })
+    $redactions=@()
+    foreach($file in $files){
+        $text=[IO.File]::ReadAllText($file.FullName)
+        $values=@($secrets)
+        $generic=[regex]::Matches($text,'(?i)(?:apiKey|api_key|X-Api-Key)["'']?\s*[:=]\s*["'']?([A-Za-z0-9_+/=.-]{20,})')
+        $values+= @($generic | ForEach-Object { $_.Groups[1].Value })
+        $values=@($values | Sort-Object -Unique)
+        $count=0
+        if($file.Name -eq '20261012T034439Z-plan-readiness-merged-r4.response.jsonl'){
+            # The runner still owns an open output handle. Preserve every file offset
+            # and every non-secret byte; padding lies only inside the replaced span.
+            $edits=@()
+            foreach($value in $values){
+                foreach($match in [regex]::Matches($text,[regex]::Escape($value))){
+                    $offset=[Text.Encoding]::UTF8.GetByteCount($text.Substring(0,$match.Index))
+                    $width=[Text.Encoding]::UTF8.GetByteCount($match.Value)
+                    $replacement='[REDACTED:api-key]'.PadRight($width,' ')
+                    $edits+=@{Offset=$offset;Bytes=[Text.Encoding]::UTF8.GetBytes($replacement)}
+                }
+            }
+            if($edits.Count -gt 0 -and $PSCmdlet.ShouldProcess($file.FullName,'Redact active stream in place without moving writer offsets')){
+                $stream=[IO.File]::Open($file.FullName,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::ReadWrite)
+                try{foreach($edit in $edits){$null=$stream.Seek($edit.Offset,[IO.SeekOrigin]::Begin);$stream.Write($edit.Bytes,0,$edit.Bytes.Length);$count++};$stream.Flush()}
+                finally{$stream.Dispose()}
+            }
+        }else{
+            $clean=$text
+            foreach($value in $values){$count+=[regex]::Matches($clean,[regex]::Escape($value)).Count;$clean=$clean.Replace($value,'[REDACTED:api-key]')}
+            if($count -gt 0 -and $PSCmdlet.ShouldProcess($file.FullName,'Redact receipt key values')){[IO.File]::WriteAllText($file.FullName,$clean,[Text.UTF8Encoding]::new($false))}
+        }
+        $remaining=[IO.File]::ReadAllText($file.FullName)
+        $knownRemaining=0
+        foreach($value in $secrets){$knownRemaining+=[regex]::Matches($remaining,[regex]::Escape($value)).Count}
+        $redactions+= [ordered]@{File=$file.Name;Replaced=$count;KnownKeysRemaining=$knownRemaining}
+    }
+    $redactions | ConvertTo-Json -Depth 5
+    if(-not $WhatIfPreference -and @($redactions | Where-Object KnownKeysRemaining -gt 0).Count -gt 0){throw 'A known marker key remains in reviewer receipts.'}
+    return
+}
+
+if($Stage -eq 'Persist'){
+    if(-not $PSCmdlet.ShouldProcess($reviewSession+'/'+$reviewRequest,'Persist full Markdown and JSON receipts, decisions, and readback proof')){return}
+    $md=[IO.File]::ReadAllText($mdPath)
+    $js=[IO.File]::ReadAllText($jsonPath)
+    $ack=Invoke-ReviewerMethod -Method 'workflow.sessionlog.updateTurn' -Parameters @{
+        response=$md
+        interpretation='One independent hostile plan-readiness review of merged PLAN-SESSIONTURNREVIEW-001 round 4. Review-only; actual Codex gpt-6-astra max verified; no time bound.'
+        designDecisions=@('DISAGREE at 92 accuracy / 90 completeness: fourteen material implementer fixes and no operator decision. Verified contracts and source take precedence over implementer self-review; no plan or product edit is authorized. See full receipts and re-attack record.')
+        filesModified=@('docs/receipts/hv/hostile-validator-plan-readiness-merged-r4-20261012T034439Z.md','docs/receipts/hv/hostile-validator-plan-readiness-merged-r4-20261012T034439Z.json','docs/receipts/hv/20261012T034439Z-review-command.ps1','docs/receipts/hv/20261012T034439Z-write-review.ps1','docs/receipts/hv/20261012T034439Z-finalize-review.ps1')
+        tags=@('PLAN-SESSIONTURNREVIEW-001','hostile-validator','round-4','review-only')
+    }
+    $ack | ConvertTo-Json -Depth 6
+    $null=Invoke-ReviewerMethod -Method 'workflow.sessionlog.appendActions' -Parameters @{actions=@(@{order=4;type='create';status='completed';description='Authored round-four Markdown/JSON receipts from native PowerShell objects, including 12 claims, 19 prior-finding re-attacks, 14 implementer findings, source evidence, exact corrections, command exit codes, model/effort metadata, profile/memory confirmation and publication proof. No product or plan file changed.';filePath='docs/receipts/hv/hostile-validator-plan-readiness-merged-r4-20261012T034439Z.md'})}
+    $width=10000
+    $total=[int][Math]::Ceiling($js.Length/[double]$width)
+    for($start=0;$start -lt $js.Length;$start+=$width){
+        $ordinal=[int]($start/$width)+1
+        $part=$js.Substring($start,[Math]::Min($width,$js.Length-$start))
+        $result=Invoke-ReviewerMethod -Method 'workflow.sessionlog.appendDialog' -Parameters @{dialogItems=@(@{timestamp=[DateTime]::UtcNow.ToString('o');role='model';category='observation';content=('R4 JSON RECEIPT PART '+$ordinal+'/'+$total+"`n"+$part)})}
+        [pscustomobject]@{Part=$ordinal;Total=$total;Persisted=$result.persisted} | ConvertTo-Json -Compress
+    }
+    $proof=Get-ReviewerReceiptProof
